from itertools import cycle, islice
from typing import List, Optional

from taf.rfrl.csv4all.resources.test_cases.cell_operation_test import CellOperationTest
from taf.rfrl.csv4all.resources.test_cases.exceptions import TestPreconditionFailed
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.test_global_constants import KPI_PER_TEST_CASE


class CellBlockUnblockTest(CellOperationTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 rat: Optional[str] = None, stop_test_after_fail: bool = False,
                 l3_call_method: Optional[callable] = None, detailed_console_log: bool = True,
                 collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, rat, stop_test_after_fail, l3_call_method,
                         detailed_console_log, collect_passed_logs)
        self.kpi_to_calculate = KPI_PER_TEST_CASE.get("Cell Block")

    def set_iterator_for_blocked_cells(self):
        for node in self.test_nodes:
            if not hasattr(node, "cells_to_block"):
                cells_to_block = [cell for cell, cell_info in node.cells_per_rat.get(self.rat).items()
                                  if not cell_info.get("IoT Cell")]
            else:
                cells_to_block = node.cells_to_block
            node.cells_to_block = iter(islice(cycle(cells_to_block), 2 * self.iterations_per_node))

    def test_setup(self):
        super().test_setup()
        self.set_iterator_for_blocked_cells()

    def set_blocked_cells(self, node, blocked_cell):
        node.btsverify.blocked_objects.append(blocked_cell)
        if node.cells_per_rat[self.rat][blocked_cell].get("Linked IoT Cell"):
            node.btsverify.blocked_objects.append(node.cells_per_rat[self.rat][blocked_cell].get("Linked IoT Cell"))

    def test_operation(self, node):
        blocked_cell = next(node.cells_to_block)
        if self.l3_call_method:
            self.l3_call_dependent_cells = [cell for cell in node.btsverify.cells_verifier.blocked_cell]
        self.block_cell(node, blocked_cell)
        self.failed_nodes[node.node_alias].update(self.run_verification(hw_timer=90, alarm_timer=30))
        self.multi_runner.start_watching_alarms_on_all_nodes()
        self.multi_runner.start_log_tracing_all_nodes()
        self.unblock_cell(node, blocked_cell)
        self.remove_cells_from_energy_saving_cells(node, blocked_cell)

    def add_allowed_faults(self, node, blocked_cell):
        node.add_test_specific_alarm("49", blocked_cell)
        if node.cells_per_rat[self.rat][blocked_cell].get("Linked IoT Cell"):
            node.add_test_specific_alarm("49", node.cells_per_rat[self.rat][blocked_cell].get("Linked IoT Cell"))

    def remove_allowed_faults(self, node, blocked_cell):
        node.remove_test_specific_alarm("49", blocked_cell)
        if node.cells_per_rat[self.rat][blocked_cell].get("Linked IoT Cell"):
            node.remove_test_specific_alarm("49", node.cells_per_rat[self.rat][blocked_cell].get("Linked IoT Cell"))

    @method_decorator()
    def block_cell(self, node, blocked_cell):
        self.set_blocked_cells(node, blocked_cell)
        node.btsverify.set_blocked_object()
        self.add_allowed_faults(node, blocked_cell)
        self.add_allowed_dss_faults_as_test_specific(node.btsverify.blocked_objects)
        node.block(blocked_cell)

    @method_decorator()
    def unblock_cell(self, node, blocked_cell):
        node.unblock(blocked_cell)
        node.btsverify.clear_blocked_objects_list()

    def run_test_precondition(self):
        try:
            super().run_test_precondition()
        except TestPreconditionFailed as e:
            for node in self.test_nodes:
                next(node.cells_to_block)
            raise e
